const sh = wb.getWorksheet('Sheet1');
const label = (n: number) => { let s = ''; while (n > 0) { n--; s = String.fromCharCode(97 + n % 26) + s; n = Math.floor(n / 26); } return s; };
let base: any = null, k = 0, wrote = 0;
for (let r = 2; r <= 89; r++) {
  const c = sh.getRange('A' + r);
  const v = c.getValue();
  if (v === null || v === undefined || v === '') {
    k++;
    c.setValue("'" + base + label(k));
    wrote++;
  } else if (typeof v === 'number') {
    base = v; k = 0;
  } else {
    k++; // existing typed label, e.g. 5a
    const expected = String(base) + label(k);
    if (String(v).replace(/^'/, '') !== expected) warn('mismatch at A' + r + ': ' + v + ' vs ' + expected);
  }
}
log('wrote', wrote);
wb.getRange('Sheet1!A1:A90')

